5. ABI-библиотеки (ядро системы)

Каждая библиотека — отдельный shared object, заменяющий Windows DLL:
5.1. kernel32.so (Core System)
c

// src/libs/kernel32/kernel32.c
#define EXPORT __attribute__((visibility("default")))

// Memory management
EXPORT LPVOID WINAPI VirtualAlloc(LPVOID, SIZE_T, DWORD, DWORD) {
return mmap(NULL, size, PROT_READ|PROT_WRITE,
MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
}

// File I/O
EXPORT HANDLE WINAPI CreateFileA(LPCSTR, DWORD, DWORD, void*, DWORD, DWORD, HANDLE) {
int fd = open(name, flags, mode);
return (HANDLE)(intptr_t)fd;
}

// Time
EXPORT DWORD WINAPI GetTickCount() {
struct timespec ts;
clock_gettime(CLOCK_MONOTONIC, &ts);
return ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

5.2. user32.so (Window System)
c

// src/libs/user32/user32.c
EXPORT HWND WINAPI CreateWindowExA(DWORD, LPCSTR, LPCSTR, DWORD,
int, int, int, int,
HWND, HMENU, HINSTANCE, LPVOID) {
struct lxfw_window* win = lxfw_wayland_create_window(width, height);
return (HWND)win;
}

EXPORT BOOL WINAPI DestroyWindow(HWND hWnd) {
lxfw_wayland_destroy_window((struct lxfw_window*)hWnd);
return TRUE;
}

5.3. d3d11.so (3D Graphics)
c

// src/libs/d3d11/d3d11.c
EXPORT HRESULT WINAPI D3D11CreateDevice(void*, D3D_DRIVER_TYPE, HMODULE,
UINT, const D3D_FEATURE_LEVEL*,
UINT, UINT, ID3D11Device**,
D3D_FEATURE_LEVEL*, ID3D11DeviceContext**) {
VkDevice vk_device = lxfw_vulkan_create_device();
*device = lxfw_wrap_vk_device(vk_device);
return S_OK;
}

6. Универсальный протокол (ядро перевода)
c

// src/core/protocol/command.h
// Бинарный протокол для всех вызовов
#pragma pack(push, 1)
struct lxfw_command {
uint32_t magic;      // 0x4C584657 "LXFW"
uint16_t version;    // 1
uint16_t category;   // GRAPHICS, WINDOW, AUDIO, INPUT, NETWORK
uint32_t opcode;     // Конкретная операция
uint32_t data_size;  // Размер данных
uint8_t  data[];     // Параметры
};
#pragma pack(pop)

// Категории операций
enum lxfw_category {
LXFW_GRAPHICS = 1,
LXFW_WINDOW   = 2,
LXFW_AUDIO    = 3,
LXFW_INPUT    = 4,
LXFW_NETWORK  = 5,
LXFW_SYSTEM   = 6
};

// Графические операции
enum lxfw_graphics_op {
LXFW_DRAW_TRIANGLES = 1,
LXFW_CLEAR          = 2,
LXFW_PRESENT        = 3,
LXFW_CREATE_BUFFER  = 4,
LXFW_CREATE_TEXTURE = 5
};

7. Механизм инжекции
c

// src/core/inject/preload.c
// Автоматическая подмена библиотек через LD_PRELOAD
__attribute__((constructor))
static void lxfw_init() {
// 1. Определяем, какая Windows DLL запрашивается
const char* requested = getenv("LXFW_TARGET_DLL");

// 2. Подменяем загрузку
void* (*original_dlopen)(const char*, int) = dlsym(RTLD_NEXT, "dlopen");

if (strstr(filename, "kernel32.dll") ||
strstr(filename, "KERNEL32.DLL")) {
// Возвращаем нашу реализацию
return &lxfw_kernel32;
}

// 3. Для остальных - прозрачный прокси
return original_dlopen(filename, flags);
}

8. Система сборки
cmake

# CMakeLists.txt - главный файл сборки
cmake_minimum_required(VERSION 3.16)
project(lxfw VERSION 0.1.0 LANGUAGES C)

# Настройки
set(LXFW_ABI_LIBS kernel32 user32 gdi32 d3d9 d3d11 dsound)
set(LXFW_BACKENDS wayland vulkan pipewire)

# Опции
option(LXFW_BUILD_PE_LOADER "Build PE loader" ON)
option(LXFW_USE_WINE_LOADER "Use Wine as loader" OFF)
option(LXFW_BUILD_EXAMPLES "Build examples" ON)

# Зависимости
find_package(Wayland REQUIRED)
find_package(Vulkan REQUIRED)
find_package(PipeWire REQUIRED)

# Библиотеки ABI
foreach(lib ${LXFW_ABI_LIBS})
add_library(${lib} SHARED src/libs/${lib}/${lib}.c)
target_link_libraries(${lib} lxfw_core)
set_target_properties(${lib} PROPERTIES
PREFIX ""
OUTPUT_NAME "${lib}"
)
endforeach()

# Бэкенды
foreach(backend ${LXFW_BACKENDS})
add_library(lxfw_${backend} STATIC src/backend/${backend}/*.c)
endforeach()

# Ядро
add_library(lxfw_core STATIC src/core/**/*.c)
target_link_libraries(lxfw_core ${LXFW_BACKENDS})

# Примеры
if(LXFW_BUILD_EXAMPLES)
add_executable(hello_win32 examples/hello_win32/hello.c)
target_link_libraries(hello_win32 kernel32 user32)
endif()

9. Сценарии использования
9.1. Запуск через LD_PRELOAD
bash

# 1. Компилируем Windows программу
x86_64-w64-mingw32-gcc -o app.exe app.c

# 2. Запускаем с нашими библиотеками
LD_PRELOAD="./libkernel32.so:./libuser32.so" ./app.exe

9.2. Использование Wine как загрузчика
bash

# Wine загружает EXE, а LXFW подменяет DLL
export WINEDLLOVERRIDES="kernel32=lxfw,user32=lxfw"
export LXFW_LIBRARY_PATH="/путь/к/lxfw/libs"
wine app.exe

9.3. Нативный загрузчик LXFW
bash

# Используем наш PE-загрузчик
./lxfw-loader app.exe

